import { d as giftOrders, t as db } from "../../../../../chunks/db.js";
import { r as deleteReleasingStock } from "../../../../../chunks/stock.js";
import "../../../../../chunks/dist2.js";
import { i as superValidate } from "../../../../../chunks/client2.js";
import { t as zod } from "../../../../../chunks/adapters.js";
import { n as parseJsonColumn } from "../../../../../chunks/format2.js";
import { n as idSchema, t as contentCrud } from "../../../../../chunks/crud.js";
import { u as syncAfter } from "../../../../../chunks/traceability.js";
import { t as bulkEmailSchema } from "../../../../../chunks/bulkEmail.js";
import { t as sendBulkEmailAction } from "../../../../../chunks/bulkEmail2.js";
import { t as orderSchema } from "../../../../../chunks/schema12.js";
import { desc } from "drizzle-orm";
//#region src/routes/dashboard/orders/one-time/+page.server.ts
var crud = contentCrud({
	table: giftOrders,
	label: "Order",
	addSchema: orderSchema,
	editSchema: orderSchema
});
var load = async () => {
	const [form, bulkEmailForm, rawRows] = await Promise.all([
		superValidate(zod(orderSchema)),
		superValidate(zod(bulkEmailSchema)),
		db.select().from(giftOrders).orderBy(desc(giftOrders.createdAt))
	]);
	return {
		form,
		bulkEmailForm,
		rows: rawRows.map((r) => ({
			...r,
			recipientAddress: parseJsonColumn(r.recipientAddress, {
				line1: "",
				city: "",
				postcode: ""
			})
		}))
	};
};
var actions = {
	edit: syncAfter("gift", crud.actions.edit),
	delete: async (event) => {
		const form = await superValidate(event.request.clone(), zod(idSchema));
		if (!form.valid) return crud.actions.delete(event);
		return deleteReleasingStock("gift", form.data.id, () => crud.actions.delete(event));
	},
	sendBulkEmail: sendBulkEmailAction
};
//#endregion
export { actions, load };
